const cfg = $('Config').first().json;
const f = $input.first().json;
const name = String(f['Full name'] || '').trim();
const personal = String(f['Personal email'] || '').trim();
const manager = String(f['Manager email'] || '').trim();
const buddy = String(f['Buddy email (optional)'] || '').trim();
const dept = String(f['Department'] || '').trim();
const role = String(f['Role'] || '').trim();
const start = new Date(f['Start date']);
const emailOk = s => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s);
const problems = [];
if (!name) problems.push('Full name is missing');
if (!emailOk(personal)) problems.push('Personal email is not valid');
if (!emailOk(manager)) problems.push('Manager email is not valid');
if (buddy && !emailOk(buddy)) problems.push('Buddy email is not valid');
if (isNaN(start.getTime())) problems.push('Start date is not a valid date');
if (problems.length) return [{ json: { valid: false, problems, name, manager, hrEmail: cfg.hrEmail } }];
const addBiz = (d, n) => { const r = new Date(d); const step = n < 0 ? -1 : 1; let left = Math.abs(n); while (left > 0) { r.setDate(r.getDate() + step); const w = r.getDay(); if (w !== 0 && w !== 6) left--; } return r; };
const iso = d => d.toISOString().slice(0, 10);
const ownerEmail = { 'HR': cfg.hrEmail, 'IT': cfg.itEmail, 'Manager': manager, 'Buddy': buddy || manager, 'New hire': personal };
const tasks = [];
cfg.stages.forEach((st, si) => {
  const list = st.tasks.slice();
  (cfg.departmentTasks[dept] || []).forEach(t => { if (t[2] === si) list.push([t[0], t[1], false]); });
  list.forEach(t => tasks.push({ starter: name, department: dept, stage: st.name, task: t[0], owner: t[1], ownerEmail: ownerEmail[t[1]], due: iso(addBiz(start, st.offset)), status: 'To do' }));
});
return [{ json: { valid: true, name, role, department: dept, start: iso(start), personal, manager, buddy, tasks } }];

const rec = $('Prepare record').first().json;
const folder = $input.first().json;
const link = folder.webViewLink || (folder.id ? 'https://drive.google.com/drive/folders/' + folder.id : '');
return rec.tasks.map(t => ({ json: { ...t, folderLink: link } }));

const cfg = $('Config').first().json;
const rec = $('Prepare record').first().json;
const link = $('Split into tasks').first().json.folderLink;
const first = rec.name.split(' ')[0];
const sheetUrl = 'https://docs.google.com/spreadsheets/d/' + cfg.trackerSheetId;
const mine = o => rec.tasks.filter(t => t.owner === o);
const li = arr => '<ul>' + arr.map(t => '<li>' + t.task + ' (due ' + t.due + ')</li>').join('') + '</ul>';
const out = [];
out.push({ json: { to: rec.personal, subject: 'Welcome to ' + cfg.orgName + ', ' + first,
  html: '<p>Hi ' + first + ',</p><p>We are glad you are joining as ' + rec.role + ' on ' + rec.start + '. Your shared folder is here: <a href="' + link + '">onboarding folder</a>. Please read <a href="' + cfg.guideLink + '">how we work</a> before your first day.</p><p>Your tasks:</p>' + li(mine('New hire')) + '<p>If anything is unclear, reply to this email.</p>' } });
out.push({ json: { to: rec.manager, subject: 'Onboarding started for ' + rec.name,
  html: '<p>Onboarding for ' + rec.name + ' (' + rec.role + ', ' + rec.department + ') starts ' + rec.start + '.</p><p>Folder: <a href="' + link + '">open</a>. Tracker: <a href="' + sheetUrl + '">open</a>.</p><p>Your tasks:</p>' + li(mine('Manager')) } });
if (rec.buddy) out.push({ json: { to: rec.buddy, subject: 'You are the buddy for ' + rec.name,
  html: '<p>You have been named the onboarding buddy for ' + rec.name + '.</p><p>Your tasks:</p>' + li(mine('Buddy')) } });
out.push({ json: { to: cfg.itEmail, subject: 'Accounts needed for ' + rec.name + ' by ' + rec.tasks.find(t => t.owner === 'IT').due,
  html: '<p>Please create accounts and prepare equipment for ' + rec.name + ' (' + rec.role + ', ' + rec.department + '), starting ' + rec.start + '.</p>' + li(mine('IT')) } });
return out;

const win = $('Reminder settings').first().json.windowDays;
const today = new Date(); today.setHours(0, 0, 0, 0);
const groups = {};
for (const it of $input.all()) {
  const r = it.json;
  if (!r.task || String(r.status).toLowerCase() === 'done' || !r.ownerEmail || !r.due) continue;
  const due = new Date(r.due); if (isNaN(due.getTime())) continue;
  const late = Math.round((today - due) / 86400000);
  if (late < 0 || late > win) continue;
  (groups[r.ownerEmail] = groups[r.ownerEmail] || []).push({ ...r, late });
}
return Object.keys(groups).map(to => {
  const rows = groups[to].sort((a, b) => b.late - a.late);
  const li = rows.map(r => '<li>' + r.starter + ': ' + r.task + (r.late > 0 ? ' (overdue by ' + r.late + ' days)' : ' (due today)') + '</li>').join('');
  return { json: { to, subject: 'Onboarding: ' + rows.length + ' task' + (rows.length > 1 ? 's' : '') + ' need you', html: '<p>These onboarding tasks are due or overdue:</p><ul>' + li + '</ul><p>Please do them and mark them Done in the tracker.</p>' } };
});
